<?php

namespace Agent\AgentBundle\Repository;

/**
 * TypeCongesRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class PeriodeCongesRepository extends \Doctrine\ORM\EntityRepository
{
    public function periodes($typeConges,$duree) {
		$qb = $this->createQueryBuilder('c')
		->Where("c.typeConges = :typeConges")
		->andWhere("c.duree <= :duree")
                ->orderBy('c.id','ASC')
		->setParameter("typeConges", $typeConges)
		->setParameter("duree", $duree);
		return $qb->getQuery()->getResult();
	}
}
